// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    PENNY_BY_PENNY c;
    function setUp() public { c = new PENNY_BY_PENNY(); }
    function testFuzz_property(address newLogAddr) public {
        vm.assume(newLogAddr != address(0));

        LogFile initial = new LogFile();
        c.SetLogFile(address(initial));

        c.Initialized();

        bool ok;
        try c.SetLogFile(newLogAddr) { ok = true; } catch { ok = false; }

        assertTrue(!ok);
    }
}

contract LogFile {
    struct Message { address Sender; string Data; uint Val; uint Time; }
    Message[] public History;
    Message LastMsg;
    function AddMessage(address _adr,uint _val, string memory _data) public {
        LastMsg.Sender = _adr;
        LastMsg.Time = block.timestamp;
        LastMsg.Val = _val;
        LastMsg.Data = _data;
        History.push(LastMsg);
    }
}
